import cameraPhotos from '../data/cameraPhotos';
import './CameraPhotoGrid.css';

function IconEye() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path
        d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinejoin="round"
      />
      <circle cx="12" cy="12" r="3" stroke="currentColor" strokeWidth="1.75" />
    </svg>
  );
}

function IconStar() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path
        d="m12 3 2.2 5.2 5.6.5-4.2 3.7 1.3 5.5L12 15.8 7.1 18l1.3-5.5-4.2-3.7 5.6-.5L12 3Z"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function IconRepost() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path
        d="M17 3h4v4M3 11V7h4M20 7a8 8 0 0 0-14.5-2M4 17a8 8 0 0 0 14.5 2"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

export default function CameraPhotoGrid() {
  return (
    <section className="camera-gallery" aria-label="Photo gallery">
      <div className="camera-gallery__masonry">
        {cameraPhotos.map((photo, i) => (
          <article key={i} className="camera-photo">
            <div
              className="camera-photo__media"
              style={{ aspectRatio: photo.aspectRatio }}
            >
              <img src={photo.src} alt={photo.alt} loading="lazy" />
              <button type="button" className="camera-photo__stats-pill">
                See more stats
              </button>
            </div>
            <div className="camera-photo__meta">
              <span className="camera-photo__stat">
                <IconEye />
                {photo.views}
              </span>
              <span className="camera-photo__stat">
                <IconStar />
                {photo.saves}
              </span>
              <span className="camera-photo__stat">
                <IconRepost />
                {photo.shares}
              </span>
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}
